    gilded_glass_blower_pipe = { name = "Pozlačena pijavka za pihanje stekla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2280, prestige = 19, happiness = 5, description = "Pozlačena pijavka za dvorne steklarje." },
