    sovereign_glassblowerpipe_palace = { name = "Suverena pijavkarska palača", cost = { gold = 13300, wood = 635, stone = 840, gold = 85, jewel = 19 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
GlassBlowerPipeMaker.ironStock = 14; GlassBlowerPipeMaker.bronzeStock = 12; GlassBlowerPipeMaker.woodStock = 12; GlassBlowerPipeMaker.leatherStock = 10; GlassBlowerPipeMaker.silverStock = 8; GlassBlowerPipeMaker.goldStock = 6; GlassBlowerPipeMaker.jewelStock = 4; GlassBlowerPipeMaker.pearlStock = 4
GlassBlowerPipeMaker.productStock = {}; GlassBlowerPipeMaker.buildings = {}; GlassBlowerPipeMaker.maker = nil; GlassBlowerPipeMaker.activeMaking = {}; GlassBlowerPipeMaker.totalProducts = 0; GlassBlowerPipeMaker.dayTimer = 0
function GlassBlowerPipeMaker.init() GlassBlowerPipeMaker.ironStock=14; GlassBlowerPipeMaker.bronzeStock=12; GlassBlowerPipeMaker.woodStock=12; GlassBlowerPipeMaker.leatherStock=10; GlassBlowerPipeMaker.silverStock=8; GlassBlowerPipeMaker.goldStock=6; GlassBlowerPipeMaker.jewelStock=4; GlassBlowerPipeMaker.pearlStock=4; GlassBlowerPipeMaker.productStock={}; GlassBlowerPipeMaker.buildings={}; GlassBlowerPipeMaker.maker=nil; GlassBlowerPipeMaker.activeMaking={}; GlassBlowerPipeMaker.totalProducts=0; GlassBlowerPipeMaker.dayTimer=0; print("[GlassBlowerPipeMaker] Royal Glass Blower Pipe Maker System initialized (6 products, 4 buildings)") end
function GlassBlowerPipeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBlowerPipeMaker.maker={name=n or ("Pijavkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pijavkar najet: %s (spretnost: %d)",GlassBlowerPipeMaker.maker.name,s),"success") end; return true end
function GlassBlowerPipeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBlowerPipeMaker.build(id) local ok,e=GlassBlowerPipeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBlowerPipeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBlowerPipeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassBlowerPipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBlowerPipeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassBlowerPipeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassBlowerPipeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassBlowerPipeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassBlowerPipeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassBlowerPipeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBlowerPipeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBlowerPipeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassBlowerPipeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassBlowerPipeMaker.buildings==0 then return false,"Potrebna pijavkarska delavnica" end; if not GlassBlowerPipeMaker.maker then return false,"Potreben pijavkar" end; return true end
function GlassBlowerPipeMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassBlowerPipeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassBlowerPipeMaker.ironStock=GlassBlowerPipeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassBlowerPipeMaker.bronzeStock=GlassBlowerPipeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassBlowerPipeMaker.woodStock=GlassBlowerPipeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassBlowerPipeMaker.leatherStock=GlassBlowerPipeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassBlowerPipeMaker.silverStock=GlassBlowerPipeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassBlowerPipeMaker.goldStock=GlassBlowerPipeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBlowerPipeMaker.jewelStock=GlassBlowerPipeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassBlowerPipeMaker.pearlStock=GlassBlowerPipeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassBlowerPipeMaker.maker then t=math.max(1,t-math.floor(GlassBlowerPipeMaker.maker.skill/13)) end; table.insert(GlassBlowerPipeMaker.activeMaking,{id="glassblowerpipe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBlowerPipeMaker.completeMaking(m) local q=1.0+(GlassBlowerPipeMaker.getQualityBonus()/100); if GlassBlowerPipeMaker.maker then q=q+(GlassBlowerPipeMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBlowerPipeMaker.productStock[m.productType]=(GlassBlowerPipeMaker.productStock[m.productType] or 0)+m.quantity; GlassBlowerPipeMaker.totalProducts=GlassBlowerPipeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBlowerPipeMaker.maker then GlassBlowerPipeMaker.maker.itemsMade=GlassBlowerPipeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBlowerPipeMaker.maker.skill=math.min(100,GlassBlowerPipeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pijavka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassblowerpipe.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassBlowerPipeMaker.update(dt) if not _G.state then return end; GlassBlowerPipeMaker.dayTimer=GlassBlowerPipeMaker.dayTimer+dt; if GlassBlowerPipeMaker.dayTimer>=30 then GlassBlowerPipeMaker.dayTimer=0; for i=#GlassBlowerPipeMaker.activeMaking,1,-1 do local m=GlassBlowerPipeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBlowerPipeMaker.completeMaking(m); table.remove(GlassBlowerPipeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBlowerPipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBlowerPipeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBlowerPipeMaker.getStats() return {ironStock=GlassBlowerPipeMaker.ironStock,bronzeStock=GlassBlowerPipeMaker.bronzeStock,woodStock=GlassBlowerPipeMaker.woodStock,leatherStock=GlassBlowerPipeMaker.leatherStock,silverStock=GlassBlowerPipeMaker.silverStock,goldStock=GlassBlowerPipeMaker.goldStock,jewelStock=GlassBlowerPipeMaker.jewelStock,pearlStock=GlassBlowerPipeMaker.pearlStock,productStock=GlassBlowerPipeMaker.productStock,numBuildings=#GlassBlowerPipeMaker.buildings,hasMaker=GlassBlowerPipeMaker.maker~=nil,makerName=GlassBlowerPipeMaker.maker and GlassBlowerPipeMaker.maker.name or "—",makerSkill=GlassBlowerPipeMaker.maker and GlassBlowerPipeMaker.maker.skill or 0,activeMaking=#GlassBlowerPipeMaker.activeMaking,totalProducts=GlassBlowerPipeMaker.totalProducts} end
